/**
 * ClaraLight Design — the anchored overlay surface.
 *
 * Popover and Tooltip only. Split out of `base.css` because it is the one part
 * of the language a project can decline: a build with neither component has no
 * use for the tail padding, the probe or the grow-from-the-tail entrance.
 *
 * Tokens live in `theme.css`; the tail itself is constructed in
 * `src/lib/anchored.tsx`, which is the other half of this file.
 *
 *   @import "tailwindcss";
 *   @import "@claralight-design/react/styles.css";
 */

@layer components {
  /**
   * Popovers and tooltips.
   *
   * The pointing arrow is *not* a second element. It is spliced into the
   * surface's own smooth-corner path, so fill, backdrop blur and the 1px
   * outline cross the join as one shape — see `src/lib/anchored.tsx`. A
   * separate arrow element cannot do that here: ClaraLight's frost fill is
   * translucent, so an overlap would composite into a visible dark seam and
   * the body's outline would run straight through the arrow's mouth.
   *
   * The consequence for CSS is this padding. The tail lives *inside* the
   * element's box, occupying `--cl-arrow-extent` on whichever side faces the
   * anchor, so content has to be inset by that much again or it would sit in
   * the tail. `[data-side]` is Base UI's, and names the side of the *anchor*
   * the surface was placed on — so the tail is on the opposite edge.
   */
  .cl-anchored {
    padding: var(--cl-anchored-padding-y) var(--cl-anchored-padding-x);
  }

  .cl-anchored-arrow[data-side="top"] {
    padding-bottom: calc(var(--cl-anchored-padding-y) + var(--cl-arrow-extent));
  }

  .cl-anchored-arrow[data-side="bottom"] {
    padding-top: calc(var(--cl-anchored-padding-y) + var(--cl-arrow-extent));
  }

  .cl-anchored-arrow[data-side="left"] {
    padding-right: calc(var(--cl-anchored-padding-x) + var(--cl-arrow-extent));
  }

  .cl-anchored-arrow[data-side="right"] {
    padding-left: calc(var(--cl-anchored-padding-x) + var(--cl-arrow-extent));
  }

  /**
   * Base UI positions this as its arrow element; ClaraLight never paints it.
   * It is a measurement probe: Floating UI writes the already-clamped arrow
   * offset onto it as inline `left`/`top`, and `AnchoredSurface` reads its box
   * to place the tail. Sized so that clamp accounts for the real tail width.
   */
  .cl-anchor-probe {
    width: var(--cl-arrow-width);
    height: var(--cl-arrow-extent);
    pointer-events: none;
    visibility: hidden;
  }


  /**
   * The entrance and exit: the surface grows out of its own tail, then returns
   * to that same point.
   *
   * A dialog nudges into place — `--cl-enter-scale` is 0.95 for it, because a
   * modal has no fixed point to grow from. An anchored overlay does: the tail's
   * tip sits against the anchor and does not move while the surface opens, so
   * the surface starts at **zero** and unfolds from that point. That is what
   * makes the overlay read as pointing at its anchor instead of appearing near
   * it, and it is why this is a second entrance rather than a value change to
   * `.cl-enter-root`.
   *
   * No opacity leg on the way in, unlike `.cl-enter-root`: at scale 0 there is
   * nothing on screen to fade, and the surface ClaraLight draws arrives opaque
   * and grows. Opacity is what the reduced-motion fallback uses instead.
   *
   * The origin is not here. It is a measured length that only the component
   * knows — where on the edge the tail actually landed — so `AnchoredSurface`
   * writes it inline; see `src/lib/anchored.tsx`.
   */
  .cl-anchored-root {
    transition: scale var(--cl-duration-enter) var(--ease-cl-spring-overlay);
  }

  .cl-anchored-root:has(> [data-ending-style]) {
    transition-duration: var(--cl-duration-exit);
  }

  .cl-anchored-root:has(> [data-starting-style]),
  .cl-anchored-root:has(> [data-ending-style]) {
    scale: 0;
  }

  /**
   * Reduced motion drops the growth — the one part that is movement — and keeps
   * the overlay legible with a short fade at the reduced duration. Same split as
   * the Flutter overlay, which reserves opacity for exactly this case.
   */
  @media (prefers-reduced-motion: reduce) {
    .cl-anchored-root {
      transition: opacity var(--cl-duration-reduced) var(--ease-cl-out);
    }

    .cl-anchored-root:has(> [data-starting-style]),
    .cl-anchored-root:has(> [data-ending-style]) {
      scale: none;
      opacity: 0;
    }
  }
}

/**
 * The arithmetic behind a numeric field's scrub gesture.
 *
 * ## Why this is not Base UI's scrub arithmetic
 *
 * `NumberField.ScrubArea` already solves the hard platform problems — pointer
 * lock, a virtual cursor that wraps at the viewport edge, suppressing touch
 * scroll — and ClaraLight keeps all of it. What it cannot keep is the increment
 * rule. Base UI accumulates pointer movement until it passes `pixelSensitivity`
 * and then applies `movementX * step` in one go, which makes the value's rate
 * depend on how the browser happened to coalesce pointer events.
 *
 * ClaraLight draws a ruler under the pointer while scrubbing, and a ruler is a
 * promise: **one tick crossing the centre line is exactly one step**. That only
 * holds if the mapping is `deltaX / spacing` with the fractional remainder
 * carried to the next event, which is what `advanceScrub` does. So the scrub
 * area's own rule is neutralised (see `number-input.tsx`) and this runs instead.
 *
 * ## Precision comes from the other axis
 *
 * Horizontal movement changes the value; vertical movement changes how much
 * horizontal movement one step costs. Dragging *down* stretches the ruler and
 * buys precision, dragging *up* compresses it — the convention Figma, Blender
 * and After Effects share. The bands are latched rather than continuous, with
 * hysteresis at each boundary, so a hand that wavers on a boundary does not
 * flicker between two sensitivities.
 *
 * Every value here is the Flutter field's, so the two platforms scrub at
 * identical rates: `_NumericScrubMetrics` in `inputs/text_field.dart`.
 */

/** Pixels of horizontal travel per step at the neutral band. */
export const SCRUB_BASE_SPACING = 8;

/** Vertical distance at which the first precision band is entered. */
export const SCRUB_INNER_BAND = 50;

/** Vertical distance at which the second precision band is entered. */
export const SCRUB_OUTER_BAND = 150;

/** Slack a band keeps before giving the pointer back to its neighbour. */
export const SCRUB_BAND_HYSTERESIS = 4;

/** How long the ruler takes to settle after a band change, in milliseconds. */
export const SCRUB_SPACING_TRANSITION = 80;

/**
 * Which precision band the gesture is latched into.
 *
 * Negative is upward travel and coarser; positive is downward and finer. `0`
 * is the neutral band the gesture starts in.
 */
export type ScrubTier = -2 | -1 | 0 | 1 | 2;

/**
 * Steps per pixel relative to the neutral band: `4` covers four times the
 * ground for the same movement, `0.25` a quarter of it.
 */
const TIER_MULTIPLIER: Record<ScrubTier, number> = {
  [-2]: 4,
  [-1]: 2,
  0: 1,
  1: 0.5,
  2: 0.25,
};

/**
 * The band `dy` belongs in, given the band it is currently in.
 *
 * Latched, not computed from `dy` alone: leaving a band needs `dy` to clear its
 * boundary by `SCRUB_BAND_HYSTERESIS`, entering only needs to reach it. The
 * loop re-runs because a single large jump — a coalesced move, or a pointer
 * that was warped across the viewport — can cross more than one boundary.
 */
export function nextScrubTier(tier: ScrubTier, dy: number): ScrubTier {
  let current = tier;
  for (;;) {
    const previous = current;
    switch (current) {
      case -2:
        if (dy >= -SCRUB_OUTER_BAND + SCRUB_BAND_HYSTERESIS) current = -1;
        break;
      case -1:
        if (dy <= -SCRUB_OUTER_BAND) current = -2;
        else if (dy >= -SCRUB_INNER_BAND + SCRUB_BAND_HYSTERESIS) current = 0;
        break;
      case 0:
        if (dy <= -SCRUB_INNER_BAND) current = -1;
        else if (dy >= SCRUB_INNER_BAND) current = 1;
        break;
      case 1:
        if (dy <= SCRUB_INNER_BAND - SCRUB_BAND_HYSTERESIS) current = 0;
        else if (dy >= SCRUB_OUTER_BAND) current = 2;
        break;
      case 2:
        if (dy <= SCRUB_OUTER_BAND - SCRUB_BAND_HYSTERESIS) current = 1;
        break;
    }
    if (current === previous) return current;
  }
}

/** Pixels of horizontal travel one step costs in a band — the ruler's pitch. */
export function scrubSpacing(tier: ScrubTier): number {
  return SCRUB_BASE_SPACING / TIER_MULTIPLIER[tier];
}

export interface ScrubAdvanceOptions {
  /** Sub-step remainder carried from the previous event, in steps. */
  progress: number;
  /** Horizontal pointer movement since the previous event, in pixels. */
  deltaX: number;
  /** Pixels per step, from `scrubSpacing`. */
  spacing: number;
  /** Whether the value can still move the given way. Asked before and after. */
  canStep: (direction: 1 | -1) => boolean;
  /** Applies whole steps. Never called with zero. */
  applySteps: (steps: number) => void;
}

/**
 * Advance the gesture by one pointer event and return the remainder to carry.
 *
 * The remainder is what makes slow scrubbing work: at 32px per step a typical
 * 2px pointer move is 1/16th of a step, and dropping it would mean the value
 * never changed at all. It is dropped deliberately in two places, both of which
 * are the pointer pushing against a bound — carrying a remainder accumulated
 * against `max` would make the value jump the moment the drag turned around.
 */
export function advanceScrub({
  progress,
  deltaX,
  spacing,
  canStep,
  applySteps,
}: ScrubAdvanceOptions): number {
  if (deltaX === 0) return progress;

  const direction = deltaX > 0 ? 1 : -1;
  if (!canStep(direction)) return 0;

  const combined = progress + deltaX / spacing;
  const steps = Math.trunc(combined);
  if (steps === 0) return combined;

  applySteps(steps);
  return canStep(steps > 0 ? 1 : -1) ? combined - steps : 0;
}

/**
 * Whole steps between `value` and a bound, or `null` when unbounded.
 *
 * This is what truncates the ruler: past the last reachable tick there is
 * nothing to draw, so the gesture's remaining range is visible rather than
 * something the user discovers by pushing into a wall.
 *
 * The tolerance is what keeps `0.1 + 0.2` from costing a tick. A distance that
 * is a whole number of steps to within floating-point noise is that many steps;
 * anything else rounds up, because a partial step is still a tick the value can
 * reach (it lands on the bound, clamped).
 */
export function stepsToBoundary(
  boundary: number | undefined,
  value: number,
  step: number,
  increasing: boolean,
): number | null {
  if (boundary === undefined || !Number.isFinite(boundary) || !Number.isFinite(step) || step <= 0) {
    return null;
  }

  const distance = increasing ? boundary - value : value - boundary;
  if (distance <= 0) return 0;

  const ratio = distance / step;
  if (!Number.isFinite(ratio)) return null;

  const nearest = Math.round(ratio);
  const tolerance = 1e-9 * Math.max(1, Math.abs(ratio));
  return Math.abs(ratio - nearest) <= tolerance ? nearest : Math.ceil(ratio);
}

/**
 * Drop the floating-point residue a chain of steps leaves behind.
 *
 * `0.1 + 0.2` is `0.30000000000000004`, and a scrub is thousands of those in a
 * row. Fifteen significant digits is the widest round-trip a double survives,
 * so this discards the error without touching a value the user actually typed.
 */
export function roundScrubbedValue(value: number): number {
  if (!Number.isFinite(value)) return value;
  return Number.parseFloat(value.toPrecision(15));
}

"use client";

import { type BorderConfig, generatePath, getLayoutSize, parseBorder } from "@lisse/core";
import {
  type ComponentProps,
  type CSSProperties,
  cloneElement,
  Fragment,
  isValidElement,
  type ReactNode,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { composeRefs, type RadiusToken } from "@/lib/squircle";
import { cn, tokenNumber } from "@/lib/utils";

/**
 * ClaraLight's anchored overlay surface — the shape behind `Popover` and
 * `Tooltip`.
 *
 * ## Why this is not `Squircle`
 *
 * A ClaraLight overlay points at its anchor, and the arrow is **part of the
 * surface**, not a second element parked against its edge. That is forced by
 * the design language rather than chosen for elegance: the frost fill is
 * translucent, so two overlapping elements composite their alpha into a
 * visible dark seam, and the 1px outline of the body would run straight across
 * the arrow's mouth. Both are plainly visible at rest, not just in motion.
 *
 * So the body and the tail are a single closed path. `Squircle` cannot express
 * that — Lisse's API takes corner options, with no way to hand it a path — so
 * this primitive owns the same three jobs `Squircle` delegates to Lisse:
 *
 *   clip-path   the fused path, which is also what clips the backdrop blur
 *   the outline an SVG stroke over the same path, because `clip-path` crops
 *               `border` (and `outline`) to nothing
 *   sync        re-measure when the surface resizes, flips side, or the anchor
 *               moves the tail — and, for a shared tooltip, drive the tail
 *               ahead of a surface that is still travelling
 *
 * It deliberately does **not** render a shadow. Anchored overlays in ClaraLight
 * sit on their outline and their blur alone.
 *
 * ## Why the body still comes from Lisse
 *
 * `generatePath` emits the Figma smoothing construction, which is the whole
 * argument in `squircle.tsx` for not using CSS `corner-shape`. Reimplementing
 * it here would fork the corner geometry of the design system, so the tail is
 * spliced into Lisse's own output instead: its straight edges are discrete
 * absolute `L` commands, which makes the splice an edit rather than a boolean
 * union.
 */

/**
 * The physical side of the anchor a surface sits on.
 *
 * Base UI also accepts the logical `inline-start` / `inline-end`, which are
 * deliberately not forwarded: with a physical side in, Base UI's resolved side
 * (and therefore `data-side`, which drives both the tail and the padding) is
 * guaranteed to be one of these four, so the geometry never has to resolve
 * writing direction to know which edge the tail belongs on.
 */
export type AnchoredSide = "top" | "bottom" | "left" | "right";

/** The tail sits on the edge facing the anchor — opposite the resolved side. */
const OPPOSITE: Record<AnchoredSide, AnchoredSide> = {
  top: "bottom",
  bottom: "top",
  left: "right",
  right: "left",
};

/** Direction of travel along each edge, following the generated path's winding. */
const ALONG: Record<AnchoredSide, Point> = {
  top: { x: 1, y: 0 },
  right: { x: 0, y: 1 },
  bottom: { x: -1, y: 0 },
  left: { x: 0, y: -1 },
};

/** Outward normal of each edge. */
const OUTWARD: Record<AnchoredSide, Point> = {
  top: { x: 0, y: -1 },
  right: { x: 1, y: 0 },
  bottom: { x: 0, y: 1 },
  left: { x: -1, y: 0 },
};

interface Point {
  x: number;
  y: number;
}

/*
 * Tail control points, as fractions of the tail's half-width and extent.
 *
 * Two cubic segments per half keep the join with the body G2 continuous, so the
 * tail grows out of the edge instead of being stuck onto it. The compact
 * `0.84` body handle controls the root rounding; the shoulder and mid controls
 * are then *derived* so that join stays C2, and mirroring preserves tangent and
 * curvature at the rounded tip, whose `0.225` handle gives a tip radius of
 * about `0.446 * extent` at the 24x7 tail ClaraLight ships.
 *
 * These are curve construction, not design values: the tail's actual size is
 * `--cl-arrow-width` and `--cl-arrow-extent`.
 */
const TAIL_BODY_CONTROL = -0.84;
const TAIL_MID = -0.5;
const TAIL_TIP_CONTROL = -0.225;
const TAIL_SHOULDER_CONTROL = (4 * TAIL_MID + TAIL_BODY_CONTROL - TAIL_TIP_CONTROL) / 4;
const TAIL_MID_CONTROL = 2 * TAIL_MID - TAIL_SHOULDER_CONTROL;

/** Sub-pixel slack when deciding whether a point sits on an edge. */
const EPSILON = 0.01;

const round = (value: number) => Number(value.toFixed(4));
const format = (point: Point) => `${round(point.x)} ${round(point.y)}`;
const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);

export interface SurfaceGeometry {
  /** Border box of the whole surface, tail included. */
  width: number;
  height: number;
  /** Side of the anchor the surface was placed on. */
  side: AnchoredSide;
  radius: number;
  smoothing: number;
  /** Whether to splice the tail in at all. */
  arrow: boolean;
  /** How far the tail reaches past the body, and its full base width. */
  extent: number;
  arrowWidth: number;
  /** Tail centre along the tail's edge, from the surface's own origin. */
  center: number;
}

export interface SurfaceOutline {
  /** The `clip-path` value: the surface's whole filled region. */
  clip: string;
  /**
   * The subpaths to stroke. One when the tail is part of the body's own
   * outline; two when the surface is a union, in which case each is stroked
   * clipped to the outside of the other so the shared join is never drawn.
   */
  outline: string[];
  /** Where the surface grows from: the tail's tip, or the anchored edge. */
  origin: Point;
  /**
   * Where the tail actually landed, after being held clear of the corners.
   *
   * The requested centre is a wish: it comes from the anchor, which can sit
   * anywhere, including off the end of the surface. This is the answer, and the
   * only value a caller may animate towards — following the wish instead would
   * chase a position the surface will not draw.
   */
  center: number;
  /**
   * The centres this surface could have drawn: how far the tail can reach along
   * its edge.
   *
   * Anything animating the tail needs this, not just the answer for one frame. A
   * follower aimed at an unreachable centre covers the whole distance to it in
   * its first step and lands on the limit — which is a jump, not a movement.
   * Aimed at the limit itself, the same follower slides.
   */
  range: { min: number; max: number };
}

/**
 * The surface's filled region and the strokes that trace its boundary.
 *
 * The tail is spliced into the body's own path whenever the anchored edge has
 * a straight run long enough to hold its base. That is the case for every
 * top and bottom overlay and for tall ones on the left or right, and it is the
 * better construction: one continuous outline, stroked in one pass.
 *
 * A short edge has no straight run at all — the corners meet in the middle of
 * it — and no amount of splicing can put a 24px base on it. There the surface
 * becomes the union of the body and a tail whose base sinks below the body's
 * outline, which is what Flutter draws too. The `clip-path` unions them by
 * winding, and the two strokes are clipped against each other.
 *
 * Both constructions need to know where the corners let go of the edge, and
 * that is read off the path Lisse emitted rather than derived from the radius —
 * see `edgeRun`.
 */
export function surfacePath(geometry: SurfaceGeometry): SurfaceOutline {
  const edge = OPPOSITE[geometry.side];
  const vertical = edge === "left" || edge === "right";
  const inset = geometry.arrow ? geometry.extent : 0;
  const bodyWidth = Math.max(0, geometry.width - (vertical ? inset : 0));
  const bodyHeight = Math.max(0, geometry.height - (vertical ? 0 : inset));
  // The body is pushed away from whichever edge the tail occupies.
  const offset: Point = { x: edge === "left" ? inset : 0, y: edge === "top" ? inset : 0 };
  const body = segments(
    generatePath(bodyWidth, bodyHeight, {
      radius: geometry.radius,
      smoothing: geometry.smoothing,
    }),
  );
  const span = vertical ? bodyHeight : bodyWidth;
  const depth = vertical ? bodyWidth : bodyHeight;

  if (!geometry.arrow || span <= 0 || depth <= 0) {
    const only = translate(body, offset);
    const middle = span / 2;
    return {
      clip: only,
      outline: [only],
      origin: edgeOrigin(edge, geometry, middle),
      center: middle,
      range: { min: middle, max: middle },
    };
  }

  const run = edgeRun(body, edge, bodyWidth, bodyHeight);
  const length = run ? run.end - run.start : 0;
  const halfWidth = fitTail(geometry.arrowWidth / 2, geometry.extent, span, run);

  if (run && length >= geometry.arrowWidth) {
    // The straight run holds the whole base, so the tail can be an edit to the
    // body's own outline. Both base ends stay on the run: a base that reached
    // into a corner would make the splice double back along the edge, which
    // self-intersects the fill and strokes the corner twice.
    const range = { min: run.start + halfWidth, max: run.end - halfWidth };
    const center = clamp(geometry.center, range.min, range.max);
    const spliced = translate(body, offset, {
      edge,
      tail: tail(edge, center, halfWidth, 0, geometry.extent, bodyWidth, bodyHeight, offset, false),
      width: bodyWidth,
      height: bodyHeight,
    });
    return {
      clip: spliced,
      outline: [spliced],
      origin: edgeOrigin(edge, geometry, center),
      center,
      range,
    };
  }

  // Keep the tail clear of the corners, or centre it when the body is too
  // small to hold it anywhere else.
  const minimum = geometry.radius + halfWidth + 1;
  const maximum = span - minimum;
  const range =
    maximum < minimum ? { min: span / 2, max: span / 2 } : { min: minimum, max: maximum };
  const center = clamp(geometry.center, range.min, range.max);
  const origin = edgeOrigin(edge, geometry, center);

  // No straight run: sink the base to where the body's outline actually is, so
  // the tail's sides cross it instead of stopping short and leaving a step.
  const startCorner = run ? run.start : span / 2;
  const endCorner = run ? span - run.end : span / 2;
  const sink = Math.min(
    depth / 2,
    Math.max(
      sunkBase(center - halfWidth, startCorner),
      sunkBase(span - center - halfWidth, endCorner),
    ) + 1,
  );
  if (halfWidth <= sink) {
    const only = translate(body, offset);
    return { clip: only, outline: [only], origin, center, range };
  }
  const bodyPath = translate(body, offset);
  const tailPath = tail(
    edge,
    center,
    halfWidth,
    -sink,
    geometry.extent,
    bodyWidth,
    bodyHeight,
    offset,
    true,
  );
  return {
    clip: `${bodyPath} ${tailPath}`,
    outline: [bodyPath, tailPath],
    origin,
    center,
    range,
  };
}

/**
 * The widest half-tail this edge can carry.
 *
 * A tail wider than the edge's straight run has to sit partly on the corners,
 * where the body's outline curves away beneath it — so the wider it gets, the
 * deeper it has to sink and the less of it stays above the surface. Rather than
 * bury a full-width tail and leave only its tip showing, narrow it until it
 * sinks by no more than a quarter of its own height, which keeps the shape
 * ClaraLight draws and simply scales it to the surface.
 */
function fitTail(halfWidth: number, extent: number, span: number, run: Run | null): number {
  if (run && run.end - run.start >= halfWidth * 2) return halfWidth;
  // Without a run the corners meet in the middle of the edge, so each one is
  // half of it; otherwise take the deeper of the two the run left behind.
  const corner = run ? Math.max(run.start, span - run.end) : span / 2;
  const budget = extent / 4;
  // Inverse of `sunkBase`: how far into the corner a base end may reach before
  // the outline has dropped further than the budget allows.
  const reach = Math.sqrt(Math.max(0, 2 * corner * budget - budget * budget));
  return Math.max(0, Math.min(halfWidth, Math.max(0, span / 2 - corner) + reach));
}

/**
 * How deep the body's outline lies at a base end that has run `distance` past
 * the start of the edge, approximating the corner as a circle of its own
 * tangency length — exact at both ends of the corner and within a fraction of
 * a pixel between them, which is all the join needs.
 */
function sunkBase(distance: number, corner: number): number {
  if (distance >= corner) return 0;
  const into = clamp(corner - distance, 0, corner);
  return corner - Math.sqrt(Math.max(0, corner * corner - into * into));
}

/** The tail's tip, in the surface's own coordinates: what the entrance grows from. */
function edgeOrigin(edge: AnchoredSide, geometry: SurfaceGeometry, center: number): Point {
  switch (edge) {
    case "top":
      return { x: center, y: 0 };
    case "bottom":
      return { x: center, y: geometry.height };
    case "left":
      return { x: 0, y: center };
    case "right":
      return { x: geometry.width, y: center };
  }
}

/**
 * The tail, entering and leaving along the edge's own direction of travel so it
 * can be dropped straight into the body's path, or closed into a subpath of its
 * own when the surface is a union.
 *
 * `base` and `tip` are the tail's two ends measured outwards from the body's
 * edge, so a negative base is one that starts below the surface it grows from.
 */
function tail(
  edge: AnchoredSide,
  center: number,
  halfWidth: number,
  base: number,
  tip: number,
  bodyWidth: number,
  bodyHeight: number,
  offset: Point,
  closed: boolean,
): string {
  const along = ALONG[edge];
  const outward = OUTWARD[edge];
  const start: Point = {
    x: (edge === "right" ? bodyWidth : edge === "left" ? 0 : center) + offset.x,
    y: (edge === "bottom" ? bodyHeight : edge === "top" ? 0 : center) + offset.y,
  };
  /** `cross` runs along the edge from the tail's centre, `out` from base to tip. */
  const point = (cross: number, out: number): Point => {
    const distance = base + out * (tip - base);
    return {
      x: start.x + along.x * cross * halfWidth + outward.x * distance,
      y: start.y + along.y * cross * halfWidth + outward.y * distance,
    };
  };
  const curve = (c1: Point, c2: Point, end: Point) =>
    `C ${format(c1)} ${format(c2)} ${format(end)}`;

  return [
    `${closed ? "M" : "L"} ${format(point(-1, 0))}`,
    curve(point(TAIL_BODY_CONTROL, 0), point(TAIL_SHOULDER_CONTROL, 0), point(TAIL_MID, 0.25)),
    curve(point(TAIL_MID_CONTROL, 0.5), point(TAIL_TIP_CONTROL, 1), point(0, 1)),
    curve(point(-TAIL_TIP_CONTROL, 1), point(-TAIL_MID_CONTROL, 0.5), point(-TAIL_MID, 0.25)),
    curve(point(-TAIL_SHOULDER_CONTROL, 0), point(-TAIL_BODY_CONTROL, 0), point(1, 0)),
    ...(closed ? ["Z"] : []),
  ].join(" ");
}

interface Splice {
  edge: AnchoredSide;
  tail: string;
  width: number;
  height: number;
}

/** One command of a generated path, with the pen positions it runs between. */
interface Segment {
  type: string;
  /** The command as written, which is what a relative corner is re-emitted as. */
  raw: string;
  from: Point;
  to: Point;
}

/**
 * Lisse's output, split into commands that know where the pen was.
 *
 * Only `M` and `L` are absolute; corners are relative `c` and `a`, but they
 * still advance the pen, and every one of them ends on its last coordinate
 * pair — which is all the tracking needs.
 */
function segments(path: string): Segment[] {
  const commands = path.match(/[A-Za-z][^A-Za-z]*/g) ?? [];
  const parsed: Segment[] = [];
  let pen: Point = { x: 0, y: 0 };

  for (const command of commands) {
    const type = command[0] ?? "";
    const from = pen;
    if (type === "M" || type === "L") {
      const numbers = (command.slice(1).match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi) ?? []).map(Number);
      pen = { x: numbers[0] ?? 0, y: numbers[1] ?? 0 };
    } else if (type !== "Z" && type !== "z") {
      const numbers = (command.slice(1).match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi) ?? []).map(Number);
      pen = { x: pen.x + (numbers.at(-2) ?? 0), y: pen.y + (numbers.at(-1) ?? 0) };
    }
    parsed.push({ type, raw: command.trim(), from, to: pen });
  }
  return parsed;
}

/** The straight part of one edge, as the interval it covers along that edge. */
interface Run {
  start: number;
  end: number;
}

/**
 * Where the corners let go of one edge, read off the body Lisse actually drew.
 *
 * Not derived from the radius, because `(1 + smoothing) * radius` is not what
 * Lisse spends on a corner: it caps the radius to half the shorter side, caps
 * the smoothing again to the corner's budget, and for a body as flat as a
 * tooltip it switches construction altogether. Each of those makes the
 * arithmetic wrong in a different direction — too long a corner sends a surface
 * to the union branch that had room to splice, too short a one lets the tail's
 * base reach into the corner, where the splice doubles back along the edge and
 * the stroke runs over the curve twice.
 *
 * The emitted path already knows the answer. Every edge carries exactly one
 * non-degenerate `L`, which is the run — the generator emits a zero-length `L`
 * after each corner as well, so length is part of the test rather than position
 * alone, and an edge whose corners meet has no run at all.
 */
function edgeRun(body: Segment[], edge: AnchoredSide, width: number, height: number): Run | null {
  const along = edge === "left" || edge === "right" ? "y" : "x";
  for (const segment of body) {
    if (segment.type !== "L") continue;
    if (!onEdge(segment.from, edge, width, height)) continue;
    if (!onEdge(segment.to, edge, width, height)) continue;
    const start = Math.min(segment.from[along], segment.to[along]);
    const end = Math.max(segment.from[along], segment.to[along]);
    if (end - start > EPSILON) return { start, end };
  }
  return null;
}

/**
 * Move the generated body into place and, when asked, insert the tail.
 *
 * Absolute commands are rewritten; relative corners come through as they were.
 * The tail replaces the `L` that runs along the target edge, which is the same
 * segment `edgeRun` measured.
 */
function translate(body: Segment[], offset: Point, splice?: Splice): string {
  const output: string[] = [];
  let inserted = false;

  for (const segment of body) {
    const { type, from, to } = segment;
    if (type === "M" || type === "L") {
      if (
        splice &&
        !inserted &&
        type === "L" &&
        onEdge(from, splice.edge, splice.width, splice.height) &&
        onEdge(to, splice.edge, splice.width, splice.height) &&
        (Math.abs(to.x - from.x) > EPSILON || Math.abs(to.y - from.y) > EPSILON)
      ) {
        output.push(splice.tail);
        inserted = true;
      }
      output.push(`${type} ${format({ x: to.x + offset.x, y: to.y + offset.y })}`);
    } else if (type === "Z" || type === "z") {
      output.push("Z");
    } else {
      output.push(segment.raw);
    }
  }
  return output.join(" ");
}

function onEdge(point: Point, edge: AnchoredSide, width: number, height: number): boolean {
  switch (edge) {
    case "top":
      return Math.abs(point.y) < EPSILON;
    case "bottom":
      return Math.abs(point.y - height) < EPSILON;
    case "left":
      return Math.abs(point.x) < EPSILON;
    case "right":
      return Math.abs(point.x - width) < EPSILON;
  }
}

/* ---------------------------------------------------------------------------
 * The component
 * ------------------------------------------------------------------------- */

export interface AnchoredSurfaceProps extends Omit<ComponentProps<"div">, "children"> {
  /** Which `--radius-*` token shapes the body's corners. */
  radius: RadiusToken;
  /**
   * Preferred side, used until Base UI reports the side it actually resolved
   * on `data-side`. Only the fallback: a flip updates the tail on its own.
   */
  side: AnchoredSide;
  /** Whether the surface points at its anchor. */
  arrow?: boolean;
  /** Figma's `xi`; defaults to `--cl-corner-smoothing`, as in `Squircle`. */
  smoothing?: number;
  /** Classes for the wrapper: placement, transform, and the entrance. */
  wrapperClassName?: string;
  /** Classes for the shape itself: fill, border, padding, text. */
  className?: string;
  /** Whether the fused tail follows a new trigger on an interruptible track. */
  tailMotion?: "none" | "fast";
  /**
   * Merge onto a single child rather than rendering a `div`. Needed for the
   * same reason as in `Squircle`: the clipped element is a Base UI part that
   * owns its own tag and behaviour.
   */
  asChild?: boolean;
  children?: ReactNode;
}

interface Appearance {
  clip: string;
  outline: string[];
  origin: Point | null;
  width: number;
  height: number;
  side: AnchoredSide;
  /** Where the tail was drawn, clamped — `null` when there is no tail to draw. */
  tailCenter: number | null;
  border?: BorderConfig;
}

/**
 * The rendered parts a tail in motion writes into directly.
 *
 * The tail's slide is a new path every frame. Committing each one to state would
 * put React's reconciler inside the animation for no gain: the *structure* is
 * settled — one surface, one clip, one stroke per subpath — and only the
 * coordinates inside it move. So the frames set attributes on these, and state
 * is committed once the tail comes to rest. See `paint`.
 */
interface Nodes {
  /** The wrapper, which carries the entrance's origin. */
  root: HTMLDivElement | null;
  svg: SVGSVGElement | null;
  /** The clip that keeps the stroke inside the surface. */
  clip: SVGPathElement | null;
  /** One stroke per subpath, each with the mask that hides its shared join. */
  strokes: (SVGPathElement | null)[];
  masks: (SVGPathElement | null)[];
}

/** Big enough to cover any surface, so `evenodd` leaves everything outside a subpath. */
const COVER = "M -9999 -9999 H 9999 V 9999 H -9999 Z";

const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

const EMPTY: Appearance = {
  clip: "",
  outline: [],
  origin: null,
  width: 0,
  height: 0,
  side: "top",
  tailCenter: null,
};

export function AnchoredSurface({
  radius,
  side,
  arrow = true,
  smoothing,
  wrapperClassName,
  className,
  asChild = false,
  children,
  ref: forwardedRef,
  style,
  tailMotion = "none",
  ...props
}: AnchoredSurfaceProps) {
  const [element, setElement] = useState<HTMLDivElement | null>(null);
  const nodes = useRef<Nodes>({ root: null, svg: null, clip: null, strokes: [], masks: [] });
  const child = asChild ? getShapeChild(children) : undefined;
  const childProps = child?.props as ComponentProps<"div"> | undefined;
  const mergedRef = useMemo(
    () => composeRefs(setElement, forwardedRef, childProps?.ref),
    [forwardedRef, childProps?.ref],
  );
  const mergedStyle = { ...style, ...childProps?.style };
  const appearance = useAppearance(element, nodes, { radius, side, arrow, smoothing, tailMotion });
  // React's own ids are not valid in a fragment reference.
  const clipId = `cl-anchored-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const shaped = appearance.clip.length > 0;

  const shapeProps = {
    ...props,
    ref: mergedRef,
    "data-cl-anchored": radius,
    style: {
      ...mergedStyle,
      // CSS intersects `border-radius` with `clip-path`, so the SSR fallback
      // has to go once the real shape lands.
      borderRadius: shaped ? undefined : (mergedStyle.borderRadius ?? `var(--radius-${radius})`),
      clipPath: shaped ? `path("${appearance.clip}")` : undefined,
    } as CSSProperties,
    className: cn("cl-anchored", arrow && "cl-anchored-arrow", className, childProps?.className),
  };
  const border = appearance.border;
  // A gradient border has no meaning for a 1px outline, and Lisse only reports
  // one when the author asked for it; a plain colour is the whole contract here.
  const stroke = shaped && border && typeof border.color === "string" ? border : undefined;

  return (
    /*
     * `.cl-anchored-root` is the entrance — the surface grows out of its tail,
     * which is the one point that does not move while it plays. Base UI's own
     * `--transform-origin` cannot say that: it is the anchor's edge, so it sits
     * in the gap *outside* the surface, and its cross-axis position is the
     * anchor's centre rather than the arrow's clamped one.
     *
     * The origin below is therefore the tail this component measured, and the
     * two have to agree: the entrance scales about the point the path draws, or
     * the surface would grow sideways out of a tail that is somewhere else.
     */
    <div
      ref={(node) => {
        nodes.current.root = node;
      }}
      className={cn("cl-anchored-root relative", wrapperClassName)}
      style={
        appearance.origin
          ? { transformOrigin: `${appearance.origin.x}px ${appearance.origin.y}px` }
          : undefined
      }
    >
      {child ? cloneElement(child, shapeProps) : <div {...shapeProps}>{children}</div>}
      {/*
        The outline is a sibling, not a border: `clip-path` crops the element's
        own border paint, and it has to trace the tail as well. Drawn at twice
        the authored width and clipped back to the surface, so the stroke lands
        wholly inside it — the same inner-border construction Lisse uses.

        When the surface is a union, each subpath is stroked clipped to the
        outside of the other, so the boundary they share — the tail's base,
        buried under the body — is never painted.
      */}
      {stroke ? (
        <svg
          ref={(node) => {
            nodes.current.svg = node;
          }}
          aria-hidden="true"
          className="pointer-events-none absolute top-0 left-0"
          width={appearance.width}
          height={appearance.height}
        >
          <defs>
            <clipPath id={clipId}>
              <path
                ref={(node) => {
                  nodes.current.clip = node;
                }}
                d={appearance.clip}
              />
            </clipPath>
            {appearance.outline.length > 1
              ? appearance.outline.map((_, index) => (
                  <clipPath
                    // biome-ignore lint/suspicious/noArrayIndexKey: the two subpaths are positional
                    key={index}
                    id={`${clipId}-${index}`}
                  >
                    <path
                      ref={(node) => {
                        nodes.current.masks[index] = node;
                      }}
                      clipRule="evenodd"
                      d={`${COVER} ${appearance.outline[index === 0 ? 1 : 0]}`}
                    />
                  </clipPath>
                ))
              : null}
          </defs>
          <g clipPath={`url(#${clipId})`}>
            {appearance.outline.map((d, index) => (
              <path
                // biome-ignore lint/suspicious/noArrayIndexKey: the two subpaths are positional
                key={index}
                ref={(node) => {
                  nodes.current.strokes[index] = node;
                }}
                d={d}
                fill="none"
                stroke={stroke.color as string}
                strokeOpacity={stroke.opacity}
                strokeWidth={stroke.width * 2}
                clipPath={appearance.outline.length > 1 ? `url(#${clipId}-${index})` : undefined}
              />
            ))}
          </g>
        </svg>
      ) : null}
    </div>
  );
}

function getShapeChild(child: ReactNode) {
  if (!isValidElement<ComponentProps<"div">>(child) || child.type === Fragment) {
    throw new Error("AnchoredSurface: `asChild` expects exactly one non-Fragment React element.");
  }
  return child;
}

const BORDER_SIDES = [
  "border-top-color",
  "border-right-color",
  "border-bottom-color",
  "border-left-color",
] as const;

interface Inputs {
  radius: RadiusToken;
  side: AnchoredSide;
  arrow: boolean;
  smoothing: number | undefined;
  tailMotion: "none" | "fast";
}

/** Insets Base UI writes the positioner's place with, per axis. */
const ALONG_X = ["left", "right"] as const;
const ALONG_Y = ["top", "bottom"] as const;

/** What one pass of the reader found: everything the surface's shape depends on. */
interface Measured {
  geometry: SurfaceGeometry;
  border: BorderConfig | undefined;
  /** Time to close 95% of the tail's standing gap, and the surface's own morph. */
  lead: number;
  morph: number;
}

/**
 * Measure the surface and keep the fused path in sync.
 *
 * Every input is read from the shape's own computed style rather than from
 * `documentElement`, so a locally scoped theme, a `rem` radius or an inline
 * token override all work — the same reasoning as `Squircle`'s reader.
 *
 * There is no frame polling at rest. Four things move the tail, and each one has
 * a signal: the surface resizing (`ResizeObserver`), Base UI flipping the side
 * (`data-side`), Floating UI re-solving the arrow offset, which it writes as
 * inline `left`/`top` on the probe, and the positioner being sent to a new
 * anchor, which it writes as inline insets (`[data-cl-anchor-track]`). The last
 * is what a shared tooltip changing trigger looks like, and the only one that
 * starts the motion track.
 */
function useAppearance(
  element: HTMLDivElement | null,
  nodes: { current: Nodes },
  inputs: Inputs,
): Appearance {
  const [appearance, setAppearance] = useState<Appearance>(EMPTY);
  const latest = useRef(inputs);
  latest.current = inputs;
  /** What React last rendered, which is the DOM structure a frame may write into. */
  const renderedRef = useRef(EMPTY);
  const syncRef = useRef<(() => void) | null>(null);

  useIsomorphicLayoutEffect(() => {
    if (!element) return;
    const view = element.ownerDocument.defaultView;
    if (!view) return;
    const saved = new Map<string, { value: string; priority: string }>();
    let frame: number | null = null;
    let measured: Measured | null = null;
    /** Whether the surface has changed since it was last read. */
    let stale = true;
    /** What the DOM is showing, which a frame of the motion track may have written. */
    let showing = EMPTY;
    /** The tail centre the track is holding, or `null` when the tail is at rest. */
    let leading: number | null = null;
    /** How far along its edge the tail could reach, as of the last surface built. */
    let reach: { min: number; max: number } | null = null;
    let clock = 0;
    let deadline = 0;

    const restore = () => {
      for (const [property, source] of saved) {
        if (element.style.getPropertyValue(property) === "transparent") {
          element.style.setProperty(property, source.value, source.priority);
        }
      }
      saved.clear();
    };

    const same = (a: Appearance, b: Appearance) =>
      a.clip === b.clip &&
      a.width === b.width &&
      a.height === b.height &&
      a.side === b.side &&
      a.tailCenter === b.tailCenter &&
      a.origin?.x === b.origin?.x &&
      a.origin?.y === b.origin?.y &&
      a.outline.length === b.outline.length &&
      a.outline.every((subpath, index) => subpath === b.outline[index]) &&
      a.border?.color === b.border?.color &&
      a.border?.opacity === b.border?.opacity &&
      a.border?.width === b.border?.width;

    const commit = (next: Appearance) => {
      renderedRef.current = next;
      showing = next;
      setAppearance((current) => (same(current, next) ? current : next));
    };

    /** Whether an appearance renders the outline, and with how many subpaths. */
    const structure = (value: Appearance) =>
      `${value.outline.length}:${value.clip.length > 0 && typeof value.border?.color === "string"}`;

    /**
     * Write one frame of the tail's slide straight into the DOM.
     *
     * Only the coordinates move while the tail travels, so the frames set
     * attributes on what React already rendered and leave the reconciler out of
     * the animation; the last frame commits. A frame that *would* change the
     * structure — the surface becoming a union, or its outline appearing — goes
     * through state instead, and the frame after it paints again.
     */
    const paint = (next: Appearance) => {
      if (structure(next) !== structure(renderedRef.current)) {
        commit(next);
        return;
      }
      showing = next;
      const { root, svg, clip, strokes, masks } = nodes.current;
      element.style.clipPath = `path("${next.clip}")`;
      if (root && next.origin) {
        root.style.transformOrigin = `${next.origin.x}px ${next.origin.y}px`;
      }
      svg?.setAttribute("width", String(next.width));
      svg?.setAttribute("height", String(next.height));
      clip?.setAttribute("d", next.clip);
      for (const [index, subpath] of next.outline.entries()) {
        strokes[index]?.setAttribute("d", subpath);
        const other = next.outline[index === 0 ? 1 : 0];
        if (other !== undefined) masks[index]?.setAttribute("d", `${COVER} ${other}`);
      }
    };

    const measure = (): Measured => {
      const { radius: token, side, arrow, smoothing } = latest.current;
      // Sample the authored border, not the transparent mask we leave behind.
      restore();
      const computed = view.getComputedStyle(element);
      const { width, height } = getLayoutSize(element, computed);
      const border = parseBorder(element, computed);
      const number = (name: string) => Number.parseFloat(computed.getPropertyValue(name));
      const duration = (name: string) => tokenNumber(computed.getPropertyValue(name));

      // Let the browser resolve the radius token's units and inheritance.
      const authored = element.style.borderTopLeftRadius;
      element.style.borderTopLeftRadius = `var(--radius-${token})`;
      const radius = Number.parseFloat(computed.borderTopLeftRadius);
      element.style.borderTopLeftRadius = authored;

      const resolvedSide = readSide(element) ?? side;
      const tokenSmoothing = number("--cl-corner-smoothing");
      const extent = number("--cl-arrow-extent");
      const arrowWidth = number("--cl-arrow-width");
      const drawArrow = arrow && Number.isFinite(extent) && Number.isFinite(arrowWidth);
      const geometry: SurfaceGeometry = {
        width,
        height,
        side: resolvedSide,
        radius: Number.isFinite(radius) ? Math.max(0, radius) : 0,
        smoothing: clamp(smoothing ?? (Number.isFinite(tokenSmoothing) ? tokenSmoothing : 0), 0, 1),
        arrow: drawArrow,
        extent: drawArrow ? extent : 0,
        arrowWidth: drawArrow ? arrowWidth : 0,
        center: drawArrow ? tailCenter(element, resolvedSide, width, height) : 0,
      };

      if (border) {
        for (const property of BORDER_SIDES) {
          saved.set(property, {
            value: element.style.getPropertyValue(property),
            priority: element.style.getPropertyPriority(property),
          });
          // Keep the border's width, which is what holds the content inset.
          element.style.setProperty(property, "transparent", "important");
        }
      }
      stale = false;
      return {
        geometry,
        border,
        lead: duration("--cl-duration-tooltip-tail") ?? 60,
        morph: duration("--cl-duration-tooltip-morph") ?? 180,
      };
    };

    const build = (source: Measured, center = source.geometry.center): Appearance => {
      const geometry = { ...source.geometry, center };
      const surface = geometry.width > 0 && geometry.height > 0 ? surfacePath(geometry) : undefined;
      if (surface) reach = surface.range;
      return {
        width: geometry.width,
        height: geometry.height,
        side: geometry.side,
        // The centre the surface resolved to, never the one it was asked for: the
        // tail follows what is drawn, and the ask is often out of reach.
        tailCenter: geometry.arrow ? (surface?.center ?? null) : null,
        border: source.border,
        clip: surface?.clip ?? "",
        outline: surface?.outline ?? [],
        origin: surface?.origin ?? null,
      };
    };

    /**
     * How far the surface still has to travel along the tail's edge, in px.
     *
     * The morph is a CSS transition on the positioner's insets, so the browser is
     * already holding both numbers this needs: the inline style is the inset Base
     * UI asked for — the end of the journey, which a transition does not touch —
     * and the computed style is how far along it is. Their difference is the
     * travel left, read off the browser rather than predicted from a duration and
     * a curve, which is what lets the tail survive a morph that is interrupted,
     * re-aimed, or overtaken by the anchor moving.
     */
    const remaining = (horizontal: boolean): number => {
      const track = element.closest<HTMLElement>("[data-cl-anchor-track]");
      if (!track) return 0;
      const computed = view.getComputedStyle(track);
      for (const property of horizontal ? ALONG_X : ALONG_Y) {
        const end = tokenNumber(track.style.getPropertyValue(property));
        if (end === undefined) continue;
        const now = tokenNumber(computed.getPropertyValue(property));
        if (now === undefined) continue;
        // `right` and `bottom` grow the other way down the axis.
        return property === "left" || property === "top" ? end - now : now - end;
      }
      return 0;
    };

    const stop = () => {
      if (frame !== null) {
        view.cancelAnimationFrame(frame);
        frame = null;
      }
      leading = null;
    };

    /**
     * The tail leads the surface to its new anchor, then waits for it there.
     *
     * Each frame asks for the centre that would keep the tail pointing at the
     * anchor from where the surface currently is: its resting centre, plus the
     * travel the surface has left. Early on that is far beyond the edge, so the
     * ask is brought back to the end of the straight run *before* the follower
     * sees it — the tail then slides to that limit over the time constant and
     * rides there. Aiming the follower at the raw ask instead would land it on the
     * limit in one step, because a first step of 60% of 180px is not a slide but a
     * jump. Once the surface has closed enough of the distance for the ask to come
     * back inside the run, the tail is already where it belongs and holds still on
     * screen while the surface finishes arriving.
     *
     * The follow is a time constant rather than a duration, because there is no
     * fixed distance to cover: the aim moves with the surface, and a new trigger
     * can change it mid-flight. `--cl-duration-tooltip-tail` is the time to close
     * 95% of a standing gap, which is three of those constants.
     *
     * Both halves of this movement are worth reading together when judging it: the
     * surface travels on a CSS transition and the tail on this timer, so a
     * DevTools playback rate slows one and not the other. Scale
     * `--cl-duration-tooltip-morph` and `--cl-duration-tooltip-tail` by the same
     * factor instead.
     */
    const step = (now: number) => {
      frame = null;
      if (leading === null || latest.current.tailMotion !== "fast") return;
      if (stale || measured === null) measured = measure();
      const { geometry, lead } = measured;
      const horizontal = geometry.side === "top" || geometry.side === "bottom";
      const travel = remaining(horizontal);
      const landed = Math.abs(travel) < 0.5;
      const ask = geometry.center + travel;
      const aim = reach ? clamp(ask, reach.min, reach.max) : ask;
      // Frame-rate independent, and a stalled tab cannot make it overshoot.
      const elapsed = clamp(now - clock, 0, 64);
      clock = now;
      const closed = 1 - Math.exp((-3 * elapsed) / Math.max(1, lead));
      const from = leading;
      const next = build(measured, from + (aim - from) * closed);
      paint(next);
      leading = next.tailCenter ?? from;

      // Stop on the distance left, not on the size of the last step: a step
      // small enough to stop on can still leave a tenth of a pixel to the exact
      // centre, and committing it lands as a visible nudge after the movement.
      if ((landed && Math.abs(aim - leading) < 0.1) || now > deadline) {
        stop();
        commit(build(measured));
        return;
      }
      frame = view.requestAnimationFrame(step);
    };

    const start = (from: number, morph: number) => {
      // A transition that never settles — an anchor moving under a scroll, say —
      // must not be able to keep the track alive for good.
      deadline = view.performance.now() + 2 * morph + 400;
      if (frame !== null) return;
      leading = from;
      clock = view.performance.now();
      frame = view.requestAnimationFrame(step);
    };

    /**
     * Re-read the surface and put it on screen.
     *
     * `retarget` says the signal was the tail being sent somewhere new, which is
     * the one that may start the motion track. While the track runs it owns the
     * tail, so a pass of any kind only re-measures and repaints around it.
     */
    const sync = (retarget: boolean) => {
      measured = measure();
      const { geometry, morph } = measured;
      const flipped = showing.side !== geometry.side;
      const reduced = view.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches ?? false;

      // A flip moves the tail onto another edge, where there is nothing to slide
      // along; same for a tail that was not on screen to lead from.
      if (flipped) stop();
      if (
        retarget &&
        !flipped &&
        !reduced &&
        latest.current.tailMotion === "fast" &&
        geometry.arrow &&
        showing.tailCenter !== null
      ) {
        start(showing.tailCenter, morph);
      }

      if (frame !== null && leading !== null) {
        paint(build(measured, leading));
      } else {
        commit(build(measured));
      }
      observer.takeRecords();
    };

    const observer = new view.MutationObserver(() => sync(true));
    const resize = new view.ResizeObserver(() => {
      stale = true;
      // The track re-reads on its own next frame; a pass here would do it twice.
      if (frame === null) sync(false);
    });
    const cleanup = () => {
      stop();
      observer.disconnect();
      resize.disconnect();
      syncRef.current = null;
      restore();
    };
    try {
      syncRef.current = () => sync(false);
      observer.observe(element, { attributes: true, attributeFilter: ["data-side"] });
      const probe = element.querySelector("[data-cl-anchor-probe]");
      if (probe) observer.observe(probe, { attributes: true, attributeFilter: ["style"] });
      const track = element.closest("[data-cl-anchor-track]");
      if (track) observer.observe(track, { attributes: true, attributeFilter: ["style"] });
      resize.observe(element);
      sync(false);
      return cleanup;
    } catch (error) {
      cleanup();
      throw error;
    }
  }, [element, nodes, inputs.arrow, inputs.tailMotion]);

  useIsomorphicLayoutEffect(() => {
    syncRef.current?.();
  });
  return appearance;
}

/**
 * The reader itself lives in `utils`, shared with the surface morph; it is
 * re-exported here so this module keeps the surface it had.
 */
export { tokenNumber };

/**
 * The leading number of a length or duration token, read from an element's own
 * cascade — a local theme, a scoped override or a `rem` value all resolve.
 */
export function themedNumber(
  element: Element | null | undefined,
  name: string,
): number | undefined {
  const view = element?.ownerDocument.defaultView;
  if (!element || !view) return undefined;
  return tokenNumber(view.getComputedStyle(element).getPropertyValue(name));
}

/**
 * `themedNumber` for the props Base UI cannot take as a callback.
 *
 * `sideOffset` accepts a function and is resolved during positioning, so it can
 * read the token inline; `collisionPadding` and the tooltip delays are plain
 * numbers, and reading them needs a mounted element. Running in a layout effect
 * keeps the correction ahead of paint, so a first pass on Base UI's own default
 * is never visible.
 */
export function useThemedNumber(
  ref: { current: Element | null },
  name: string,
): number | undefined {
  const [value, setValue] = useState<number>();
  useIsomorphicLayoutEffect(() => {
    const next = themedNumber(ref.current, name);
    setValue((current) => (current === next ? current : next));
  });
  return value;
}

function readSide(element: HTMLElement): AnchoredSide | undefined {
  const side = element.dataset.side;
  return side === "top" || side === "bottom" || side === "left" || side === "right"
    ? side
    : undefined;
}

/**
 * Where the tail meets the body, from the surface's own origin.
 *
 * Read off Base UI's arrow element, which Floating UI has already solved and
 * clamped against the anchor.
 *
 * Offset geometry rather than `getBoundingClientRect`, because this has to
 * survive the entrance. The wrapper scales from zero, so on the first frame
 * every rect inside it collapses to a point, and nothing can be recovered from
 * the ratio — a couple of rects at 0 measure a tail at the surface's left edge.
 * Offsets are layout space: a transform does not move them, and the measurement
 * is therefore right the first time instead of being right later, which is the
 * difference between a tail that follows the anchor and one that waits for the
 * next resize.
 *
 * An absolutely positioned box is placed from its containing block's *padding*
 * box, so a probe whose offset parent is the surface itself is short by that
 * surface's own border — and the path is drawn in border-box space. The surface
 * is the probe's containing block whenever it carries the frost, whose
 * `backdrop-filter` establishes one; the wrapper is the alternative, and it has
 * no insets of its own to correct for.
 */
function tailCenter(
  element: HTMLElement,
  side: AnchoredSide,
  width: number,
  height: number,
): number {
  const probe = element.querySelector<HTMLElement>("[data-cl-anchor-probe]");
  if (!probe) return (side === "left" || side === "right" ? height : width) / 2;
  const horizontal = side === "top" || side === "bottom";
  const border =
    probe.offsetParent === element ? (horizontal ? element.clientLeft : element.clientTop) : 0;
  return horizontal
    ? probe.offsetLeft + border + probe.offsetWidth / 2
    : probe.offsetTop + border + probe.offsetHeight / 2;
}

"use client";

import type { NumberFieldRoot } from "@base-ui/react/number-field";
import { NumberField } from "@base-ui/react/number-field";
import { Tooltip } from "@base-ui/react/tooltip";
import Scritto from "@scritto/react";
import { cva, type VariantProps } from "class-variance-authority";
import {
  type ComponentProps,
  type KeyboardEvent as ReactKeyboardEvent,
  type MouseEvent as ReactMouseEvent,
  type ReactNode,
  type PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { AnchoredSurface, themedNumber, useThemedNumber } from "@/lib/anchored";
import {
  advanceScrub,
  nextScrubTier,
  roundScrubbedValue,
  SCRUB_BASE_SPACING,
  SCRUB_SPACING_TRANSITION,
  type ScrubTier,
  scrubSpacing,
  stepsToBoundary,
} from "@/lib/scrub";
import { Squircle } from "@/lib/squircle";
import { cn } from "@/lib/utils";

/**
 * ClaraLight's numeric field — the inspector inputs of the design ("X 12px",
 * "W 78").
 *
 * It is a separate component from `Input` rather than a mode of it, because the
 * two are different elements: a numeric field is a `NumberField.Group` holding
 * an input, a stepper and two scrub handles, and Base UI owns the parsing,
 * formatting and `spinbutton` semantics that make it one control. Both draw
 * their surface from `inputVariants`' geometry, so a numeric field and a text
 * field in the same form are the same height and share an edge.
 *
 * ## The three ways to change the value
 *
 * **Type it.** Base UI parses and formats through `Intl.NumberFormat`.
 *
 * **Step it.** The chevrons, the arrow keys and the wheel each move by `step`.
 *
 * **Scrub it.** Drag the prefix or the stepper strip sideways and the value
 * follows the pointer. This is the affordance the design is built around, and
 * the rest of this file is mostly in service of it.
 *
 * The two overlap on purpose: the chevrons are inside the scrub handle, so the
 * same press can end as either a step or a drag, decided by how far the pointer
 * travels rather than by where it landed. A field with no prefix would
 * otherwise have nothing to scrub from but the few pixels of strip around two
 * 18x10 buttons. `useAdjustment` owns that arbitration, and it is why the
 * chevrons are plain buttons rather than `NumberField.Increment`.
 *
 * ## What scrubbing has to get right
 *
 * A ruler appears under the pointer while scrubbing, which turns the gesture
 * into a promise: one tick crossing the centre line is one step. Vertical
 * movement changes the ruler's pitch — drag down for precision, up for reach —
 * so the same gesture covers `0.25` and `4` steps per notch without a modifier
 * key. `lib/scrub.ts` holds that arithmetic and the reasoning behind it.
 *
 * Base UI's `ScrubArea` keeps the platform half of the gesture: pointer lock,
 * a virtual cursor that wraps at the viewport edge so a drag is never cut short
 * by the screen, and touch-scroll suppression. Its own increment rule is
 * neutralised — see `SCRUB_SENSITIVITY_OFF` — and so is its commit, which fires
 * on every release whether or not the value moved.
 *
 * ## Modifier keys deliberately do nothing
 *
 * Base UI steps by `largeStep` on shift and `smallStep` on alt. ClaraLight
 * does not: precision is the scrub gesture's vertical axis, and a field that
 * also had two hidden keyboard step sizes would have three different answers to
 * "how much is one step". A modified arrow key is left to the text caret.
 */

/** Matches `Squircle`'s guard: a layout effect has nothing to measure on a server. */
const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** Identifies which end of the range a stepper's leading chevron points at. */
export type NumberInputDirection = "up" | "down" | "left" | "right";

/**
 * Large enough that `ScrubArea`'s own accumulator can never reach it, which
 * turns its increment rule off while leaving pointer lock, the wrapping virtual
 * cursor and the pointer-up commit in place. A scrub that travelled this far
 * would have crossed the observable universe in pixels.
 */
const SCRUB_SENSITIVITY_OFF = Number.MAX_SAFE_INTEGER;

/** Movement before a press on a scrub handle is read as a drag, in pixels. */
const SCRUB_ACTIVATION_DISTANCE = 4;

/** How long a chevron is held before it starts repeating, and how fast it then does. */
const STEP_REPEAT_DELAY = 500;
const STEP_REPEAT_INTERVAL = 80;

/** Idle time after the last wheel notch before the interaction is committed. */
const WHEEL_COMMIT_DELAY = 120;

/**
 * The control surface. The geometry is `inputVariants`' so the two field types
 * line up, but the padding is the group's rather than the input's: the stepper
 * strip sits flush against the trailing edge, as it does in the design, so the
 * trailing inset belongs to the content and not to the box.
 */
export const numberInputVariants = cva(
  [
    "relative flex w-full items-center border border-outline",
    "bg-control font-mono text-foreground",
    "transition-[background-color,border-color,color] duration-(--cl-duration-fast) ease-cl-out",
    "hover:bg-control-highlight",
    "data-[disabled]:pointer-events-none data-[disabled]:text-foreground-disabled",
    "data-[invalid]:border-danger",
  ],
  {
    variants: {
      size: {
        sm: "h-control-sm text-mono",
        md: "h-control-md text-mono-strong",
        lg: "h-control-lg text-mono-strong",
      },
    },
    defaultVariants: { size: "md" },
  },
);

/** Leading inset, matching `Input`'s so the two fields share a text edge. */
const LEADING_PAD = { sm: "pl-2", md: "pl-3", lg: "pl-4" } as const;

export interface NumberInputProps
  extends Omit<
    ComponentProps<typeof NumberField.Root>,
    "className" | "onValueChange" | "onValueCommitted" | "prefix" | "render" | "step" | "suffix"
  > {
  /**
   * Shared control density. Not `VariantProps`, which would also admit `null`:
   * the size picks the leading inset from a lookup, so it has to be a key.
   */
  size?: NonNullable<VariantProps<typeof numberInputVariants>["size"]>;
  /** Amount one step moves. `0` removes the stepper and the scrub handles. */
  step?: number;
  /** Which way the leading chevron points, and therefore which keys step. */
  direction?: NumberInputDirection;
  /** Leading label, dimmed — the axis letter in the design's inspector rows. */
  prefix?: ReactNode;
  /** Trailing unit, dimmed. Hidden while scrubbing, where the readout has it. */
  suffix?: ReactNode;
  placeholder?: string;
  /** Renders the field with error colours, alongside any `Field` validation. */
  invalid?: boolean;
  /** Fires on every change, including each step of a scrub. */
  onValueChange?: (value: number | null, reason: NumberFieldRoot.ChangeEventReason) => void;
  /** Fires once when an interaction ends: pointer release, blur, or a keypress. */
  onValueCommitted?: (value: number | null, reason: NumberFieldRoot.CommitEventReason) => void;
  /** Fires when Escape abandons an interaction, with the value it restored. */
  onCancel?: (value: number | null) => void;
  /** Applied to the clipped surface: fill, border, text. */
  className?: string;
  /** Applied to the wrapper, which is what a caller's layout sizes. */
  wrapperClassName?: string;
}

export function NumberInput({
  id: idProp,
  size = "md",
  step = 1,
  direction = "up",
  prefix,
  suffix,
  placeholder,
  invalid,
  value: valueProp,
  defaultValue,
  min,
  max,
  disabled = false,
  readOnly = false,
  onValueChange,
  onValueCommitted,
  onCancel,
  className,
  wrapperClassName,
  ...props
}: NumberInputProps) {
  // The chevrons point `aria-controls` at the input, so it needs a name even
  // when the caller did not give the field one.
  const generatedId = useId();
  const id = idProp ?? generatedId;

  const [uncontrolled, setUncontrolled] = useState<number | null>(defaultValue ?? null);
  const value = valueProp === undefined ? uncontrolled : valueProp;

  /*
   * The scrub writes the value between renders — it asks whether the next step
   * is still in range immediately after applying the previous one — so the
   * authoritative value during a gesture is this ref, not the render's closure.
   */
  const valueRef = useRef(value);
  valueRef.current = value;

  const inputRef = useRef<HTMLInputElement | null>(null);
  const bodyRef = useRef<HTMLDivElement | null>(null);

  /*
   * Drawn and adjustable are separate questions. A disabled or read-only field
   * keeps the stepper, greyed and inert, so that disabling a row of inspector
   * fields never reflows it — the same reasoning as the Flutter field's.
   */
  const hasStepper = step > 0;
  const adjustable = hasStepper && !disabled && !readOnly;

  const setValue = useEvent((next: number | null, reason: NumberFieldRoot.ChangeEventReason) => {
    valueRef.current = next;
    if (valueProp === undefined) setUncontrolled(next);
    onValueChange?.(next, reason);
  });

  const canStep = useEvent((towards: 1 | -1) => {
    if (!adjustable) return false;
    const current = valueRef.current;
    if (current === null) return false;
    if (towards > 0 && max !== undefined && current >= max) return false;
    if (towards < 0 && min !== undefined && current <= min) return false;
    return true;
  });

  const bumpBy = useEvent((steps: number, reason: NumberFieldRoot.ChangeEventReason) => {
    const current = valueRef.current;
    if (current === null) return;
    let next = current + steps * step;
    if (min !== undefined && next < min) next = min;
    if (max !== undefined && next > max) next = max;
    next = roundScrubbedValue(next);
    if (next === current) return;
    setValue(next, reason);
  });

  const commit = useEvent((next: number | null, reason: NumberFieldRoot.CommitEventReason) => {
    onValueCommitted?.(next, reason);
  });

  const cancelled = useEvent((restored: number | null) => {
    onCancel?.(restored);
  });

  const { scrub, engaged, beginScrub, beginPress, dropRuler, readout } = useAdjustment({
    adjustable,
    canStep,
    bumpBy,
    commit,
    valueRef,
    setValue,
    onCancel: cancelled,
    inputRef,
  });

  useWheelStepping({ inputRef, adjustable, canStep, bumpBy, commit, valueRef });
  useEscapeRevert({
    inputRef,
    value,
    valueRef,
    setValue,
    onCancel: cancelled,
    scrubbing: scrub !== null,
  });

  /*
   * What the input is showing. Base UI owns the formatted text and keeps it
   * through partial typing ("1.", "-"), so it is read back off the element
   * rather than derived from the number — deriving it would collapse a value
   * mid-edit and take the caret with it.
   */
  const [display, setDisplay] = useState("");
  const syncDisplay = useEvent(() => {
    const text = inputRef.current?.value ?? "";
    setDisplay((previous) => (previous === text ? previous : text || (placeholder ?? "")));
  });
  useIsomorphicLayoutEffect(syncDisplay);

  const focusFromBody = useEvent((event: ReactMouseEvent) => {
    const input = inputRef.current;
    if (!input || disabled || readOnly || event.target === input) return;
    event.preventDefault();
    input.focus();
    input.setSelectionRange(input.value.length, input.value.length);
  });

  const axis = direction === "up" || direction === "down" ? "vertical" : "horizontal";
  const leading = direction === "up" || direction === "left" ? 1 : -1;

  /*
   * Base UI reads Up/Down only, and steps by `largeStep`/`smallStep` under a
   * modifier. Both are corrected here, before Base UI's own handler, which
   * bails out of anything already default-prevented.
   */
  const handleKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (!adjustable || event.defaultPrevented) return;
    const modified = event.shiftKey || event.altKey || event.ctrlKey || event.metaKey;
    const vertical = event.key === "ArrowUp" || event.key === "ArrowDown";
    const horizontal = event.key === "ArrowLeft" || event.key === "ArrowRight";

    if (modified && (vertical || horizontal)) {
      if (axis === "vertical" ? vertical : horizontal) event.preventDefault();
      return;
    }
    if (axis === "vertical" || !horizontal) return;

    // A horizontal stepper owns the horizontal arrows, so they step the value
    // rather than moving the caret — the same trade the Flutter field makes.
    event.preventDefault();
    const towards = (event.key === "ArrowLeft" ? leading : -leading) as 1 | -1;
    if (!canStep(towards)) return;
    bumpBy(towards, "keyboard");
    commit(valueRef.current, "keyboard");
  };

  const ticks =
    scrub && value !== null
      ? {
          increase: stepsToBoundary(max, value, step, true),
          decrease: stepsToBoundary(min, value, step, false),
        }
      : null;

  return (
    <NumberField.Root
      id={id}
      value={value}
      min={min}
      max={max}
      step={step > 0 ? step : "any"}
      // Precision is the scrub's vertical axis; a modified key must not be a
      // second, invisible step size. See the note at the top of this file.
      smallStep={step > 0 ? step : undefined}
      largeStep={step > 0 ? step : undefined}
      disabled={disabled}
      readOnly={readOnly}
      onValueChange={(next, details) => setValue(next, details.reason)}
      /*
       * Base UI's scrub area commits on every release, changed or not, and
       * always as `scrub`. `useAdjustment` knows whether the value actually
       * moved and whether the interaction was a drag or a chevron, so its
       * commit replaces that one rather than joining it.
       */
      onValueCommitted={(next, details) =>
        details.reason === "scrub" ? undefined : commit(next, details.reason)
      }
      className={cn("block w-full", wrapperClassName)}
      {...props}
    >
      <Squircle asChild radius="control" ring="field" wrapperClassName="block w-full">
        <NumberField.Group
          data-cl-slot="number-input"
          data-invalid={invalid || undefined}
          className={cn(numberInputVariants({ size }), hasStepper ? undefined : "pr-3", className)}
        >
          {prefix === undefined ? (
            <span aria-hidden="true" className={cn("shrink-0", LEADING_PAD[size])} />
          ) : (
            <ScrubHandle
              enabled={adjustable}
              engaged={engaged}
              onScrubStart={beginScrub}
              className={cn(
                "flex shrink-0 items-center self-stretch pr-2.5",
                LEADING_PAD[size],
                slotClass(size, false, disabled),
              )}
            >
              {prefix}
            </ScrubHandle>
          )}

          {/*
           * Clicking the empty space after the value edits the field, which it
           * would not on its own: the input is only as wide as its text, so
           * most of this box is not the input.
           */}
          {/* biome-ignore lint/a11y/noStaticElementInteractions: focus forwarding, not a control */}
          <div
            ref={bodyRef}
            onMouseDown={focusFromBody}
            className="relative flex min-w-0 flex-1 items-center self-stretch"
          >
            <div
              /*
               * The value and the ruler occupy the same box and cross-fade, so
               * the ruler reads as the field *becoming* a scale rather than as
               * a panel drawn over it.
               */
              className={cn(
                // No gap: the unit is part of the value, "12px" not "12 px".
                "flex min-w-0 flex-1 items-baseline transition-opacity ease-cl-out",
                scrub ? "opacity-0 duration-(--cl-duration-fast)" : "opacity-100",
                scrub ? undefined : "duration-(--cl-duration-exit)",
                "motion-reduce:duration-(--cl-duration-reduced)",
              )}
            >
              {/*
               * The value is only as wide as it reads, so the unit sits against
               * it — "12px", not "12" at one end of the field and "px" at the
               * other. An input has no intrinsic width, so a mirror of the same
               * text in the same font supplies one and the input is laid over
               * it. `field-sizing: content` would do this natively, but not in
               * every engine, and a field that is one width in Chromium and
               * another in Safari is worse than the machinery.
               */}
              <span className="relative block min-w-0 max-w-full shrink">
                <span aria-hidden="true" className="invisible block whitespace-pre pr-px">
                  {display}
                </span>
                <NumberField.Input
                  /*
                   * Not `NumberField.Root`'s `inputRef`, which is the hidden
                   * form input: the wheel, Escape and the readout all need the
                   * visible one, whose value is the formatted text on screen.
                   */
                  ref={inputRef}
                  placeholder={placeholder}
                  onKeyDown={handleKeyDown}
                  onInput={syncDisplay}
                  className={cn(
                    "absolute inset-0 w-full min-w-0 bg-transparent tabular-nums outline-none",
                    "placeholder:text-foreground-hint",
                    "data-[disabled]:text-foreground-disabled",
                    "data-[disabled]:placeholder:text-foreground-disabled",
                  )}
                />
              </span>
              {suffix === undefined ? null : (
                <span className={cn("shrink-0", slotClass(size, true, disabled))}>{suffix}</span>
              )}
            </div>
            {scrub === null ? null : (
              <ScrubRuler
                progress={scrub.progress}
                spacing={scrub.spacing}
                increase={ticks?.increase ?? null}
                decrease={ticks?.decrease ?? null}
                revealed={scrub.phase === "in"}
                onFadedOut={dropRuler}
              />
            )}
          </div>

          {hasStepper ? (
            <Stepper
              axis={axis}
              leading={leading}
              enabled={adjustable}
              engaged={engaged}
              controls={id}
              canStep={canStep}
              onScrubStart={beginScrub}
              onPress={beginPress}
            />
          ) : null}
        </NumberField.Group>
      </Squircle>

      <ScrubReadout
        anchor={bodyRef}
        open={scrub !== null && readout !== null}
        value={readout ?? ""}
        suffix={suffix}
      />
    </NumberField.Root>
  );
}

/** Prefix and suffix typography: dimmed, and mono only for the unit. */
function slotClass(size: "sm" | "md" | "lg", mono: boolean, disabled: boolean) {
  return cn(
    mono ? "font-mono" : "font-sans font-normal",
    mono
      ? size === "sm"
        ? "text-mono"
        : "text-mono"
      : size === "sm"
        ? "text-caption"
        : "text-callout",
    disabled ? "text-foreground-disabled" : "text-foreground-tertiary",
    "[&_svg]:shrink-0",
    size === "sm" ? "[&_svg]:size-icon-sm" : "[&_svg]:size-icon-md",
  );
}

/* -------------------------------------------------------------------------
 * The gesture
 * ---------------------------------------------------------------------- */

/**
 * A callback with a fixed identity that always runs the latest body.
 *
 * Both gestures below install listeners for the duration of an interaction, and
 * both change the value while that interaction is running. Depending on the raw
 * callbacks would tear those listeners down and rebuild them on every step —
 * which cost the wheel its commit outright, since the pending timer was
 * cancelled by the cleanup of the very render its own step had caused.
 */
function useEvent<T extends (...args: never[]) => unknown>(callback: T): T {
  const latest = useRef(callback);
  latest.current = callback;
  return useCallback(((...args: never[]) => latest.current(...args)) as T, []);
}

/** What the ruler needs to draw itself, published once per animation frame. */
interface ScrubFrame {
  progress: number;
  spacing: number;
  phase: "in" | "out";
}

interface AdjustmentSession {
  dy: number;
  tier: ScrubTier;
  progress: number;
  /** The pitch the ruler is easing away from, and the one it is easing to. */
  from: number;
  to: number;
  since: number;
  /** Total pointer travel, which is what decides press against drag. */
  moved: number;
  /** Whether the travel has passed the threshold and the drag has won. */
  engaged: boolean;
  /** The value the interaction started at, restored when Escape abandons it. */
  origin: number | null;
}

/** A chevron being held down, until the drag takes the interaction away. */
interface PressSession {
  towards: 1 | -1;
  /** Whether the hold has started repeating, which suppresses the release step. */
  repeated: boolean;
}

interface AdjustmentOptions {
  adjustable: boolean;
  canStep: (towards: 1 | -1) => boolean;
  bumpBy: (steps: number, reason: NumberFieldRoot.ChangeEventReason) => void;
  commit: (value: number | null, reason: NumberFieldRoot.CommitEventReason) => void;
  valueRef: { current: number | null };
  setValue: (value: number | null, reason: NumberFieldRoot.ChangeEventReason) => void;
  onCancel: ((value: number | null) => void) | undefined;
  inputRef: { current: HTMLInputElement | null };
}

/**
 * One interaction, two possible outcomes: a step, or a scrub.
 *
 * Press and drag are not separate regions of the control. Anywhere in the
 * stepper strip — the chevrons included — a press might become either, and
 * which one it is depends on what the pointer does next, not on where it
 * landed. That is the whole reason this is one hook: a field without a prefix
 * would otherwise have only the few pixels of strip around the chevrons to
 * scrub from, which is no affordance at all.
 *
 * The arbitration is Flutter's, and it is a distance: under
 * `SCRUB_ACTIVATION_DISTANCE` the interaction is still a press, and past it the
 * drag has won and the press is abandoned. It follows that a chevron steps on
 * *release* rather than on press — stepping on the way down would leave a stray
 * step in front of every drag that started on a button.
 *
 * The session lives in a ref and the ruler is repainted from an animation
 * frame, because a pointer at 120Hz would otherwise put React's reconciler
 * inside the gesture for no gain — the structure is settled, only numbers move.
 * What goes through state is what changes structure: whether the ruler is
 * mounted, and the value the readout shows.
 */
function useAdjustment({
  adjustable,
  canStep,
  bumpBy,
  commit,
  valueRef,
  setValue,
  onCancel,
  inputRef,
}: AdjustmentOptions) {
  const session = useRef<AdjustmentSession | null>(null);
  const press = useRef<PressSession | null>(null);
  const repeatDelay = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const repeatTick = useRef<ReturnType<typeof setInterval> | undefined>(undefined);
  const [scrub, setScrub] = useState<ScrubFrame | null>(null);
  const [active, setActive] = useState(false);
  const [engaged, setEngaged] = useState(false);
  const [readout, setReadout] = useState<string | null>(null);

  const stopRepeating = useEvent(() => {
    clearTimeout(repeatDelay.current);
    clearInterval(repeatTick.current);
    repeatDelay.current = undefined;
    repeatTick.current = undefined;
  });

  /**
   * Opens the interaction. Fires for a press anywhere in a scrub handle — the
   * chevrons bubble into it, since they deliberately leave the event alone.
   */
  const beginScrub = useEvent((event: ReactPointerEvent) => {
    if (event.defaultPrevented || !adjustable || event.button) return;
    session.current = {
      dy: 0,
      tier: 0,
      progress: 0,
      from: SCRUB_BASE_SPACING,
      to: SCRUB_BASE_SPACING,
      since: 0,
      moved: 0,
      engaged: false,
      origin: valueRef.current,
    };
    setActive(true);
  });

  /**
   * Records which chevron is down and starts its hold.
   *
   * Runs before `beginScrub`, because the button is inside the scrub handle and
   * the event reaches the target first. It deliberately does not open the
   * session: the scrub handle does that for every press alike.
   */
  const beginPress = useEvent((towards: 1 | -1, event: ReactPointerEvent) => {
    if (event.defaultPrevented || !adjustable || event.button || !canStep(towards)) return;
    stopRepeating();
    press.current = { towards, repeated: false };
    repeatDelay.current = setTimeout(() => {
      const held = press.current;
      if (!held) return;
      held.repeated = true;
      const tick = () => {
        if (!press.current || !canStep(held.towards)) {
          stopRepeating();
          return;
        }
        bumpBy(held.towards, held.towards > 0 ? "increment-press" : "decrement-press");
      };
      tick();
      repeatTick.current = setInterval(tick, STEP_REPEAT_INTERVAL);
    }, STEP_REPEAT_DELAY);
  });

  /**
   * Closes the interaction, and is the only place a commit is emitted for it.
   *
   * Base UI's scrub area commits on every release whether or not anything
   * moved, and always as `scrub`. Both are wrong here — a click on a prefix is
   * not an edit, and a chevron press is not a scrub — so that commit is dropped
   * at the root and this one replaces it.
   */
  const end = useEvent(() => {
    const current = session.current;
    const held = press.current;
    stopRepeating();
    session.current = null;
    press.current = null;
    setActive(false);
    setEngaged(false);
    if (!current) return;

    // A press that never travelled and never repeated is a click: one step.
    if (held && !held.repeated && !current.engaged && canStep(held.towards)) {
      bumpBy(held.towards, held.towards > 0 ? "increment-press" : "decrement-press");
    }
    if (valueRef.current === current.origin) return;
    commit(
      valueRef.current,
      current.engaged
        ? "scrub"
        : held
          ? held.towards > 0
            ? "increment-press"
            : "decrement-press"
          : "none",
    );
  });

  const cancel = useEvent(() => {
    const origin = session.current?.origin ?? null;
    const changed = origin !== valueRef.current;
    stopRepeating();
    session.current = null;
    press.current = null;
    setActive(false);
    setEngaged(false);
    if (!changed) return;
    setValue(origin, "none");
    onCancel?.(origin);
  });

  useEffect(() => {
    if (!active) return undefined;
    const input = inputRef.current;
    const view = input?.ownerDocument.defaultView;
    if (!view) return undefined;

    let frame = 0;

    /** The pitch part-way through its ease, so a band change is not a jump. */
    const pitch = (now: number) => {
      const current = session.current;
      if (!current) return SCRUB_BASE_SPACING;
      const elapsed = now - current.since;
      if (elapsed >= SCRUB_SPACING_TRANSITION) return current.to;
      const t = elapsed / SCRUB_SPACING_TRANSITION;
      // easeOutCubic, matching the Flutter field's spacing transition.
      const eased = 1 - (1 - t) ** 3;
      return current.from + (current.to - current.from) * eased;
    };

    const handleMove = (event: PointerEvent) => {
      const current = session.current;
      if (!current) return;
      const now = performance.now();

      current.moved += Math.abs(event.movementX) + Math.abs(event.movementY);
      current.dy += event.movementY;

      const tier = nextScrubTier(current.tier, current.dy);
      if (tier !== current.tier) {
        current.from = pitch(now);
        current.to = scrubSpacing(tier);
        current.since = now;
        current.tier = tier;
      }

      if (current.moved < SCRUB_ACTIVATION_DISTANCE) return;
      if (!current.engaged) {
        // The drag has won the interaction. Any chevron held under the pointer
        // gives it up now, before its hold could fire a step nobody asked for.
        current.engaged = true;
        press.current = null;
        stopRepeating();
        setEngaged(true);
      }
      current.progress = advanceScrub({
        progress: current.progress,
        deltaX: event.movementX,
        spacing: pitch(now),
        canStep,
        applySteps: (steps) => bumpBy(steps, "scrub"),
      });
    };

    const handleUp = () => end();
    const handleKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      cancel();
    };

    // Capture, so a scrub that runs off the field still steers it, and so the
    // session ends even if something downstream stops the release.
    view.addEventListener("pointermove", handleMove, true);
    view.addEventListener("pointerup", handleUp, true);
    view.addEventListener("pointercancel", handleUp, true);
    view.addEventListener("keydown", handleKey, true);

    const paint = () => {
      const current = session.current;
      // Nothing is drawn until the drag has won: a press that turns out to be
      // a click must not flash a ruler and a readout on its way past.
      if (current?.engaged) {
        const spacing = pitch(performance.now());
        setScrub((previous) =>
          previous && previous.progress === current.progress && previous.spacing === spacing
            ? previous
            : { progress: current.progress, spacing, phase: "in" },
        );
        setReadout(inputRef.current?.value ?? null);
      }
      frame = view.requestAnimationFrame(paint);
    };
    frame = view.requestAnimationFrame(paint);

    return () => {
      view.cancelAnimationFrame(frame);
      view.removeEventListener("pointermove", handleMove, true);
      view.removeEventListener("pointerup", handleUp, true);
      view.removeEventListener("pointercancel", handleUp, true);
      view.removeEventListener("keydown", handleKey, true);
    };
  }, [active, canStep, bumpBy, end, cancel, stopRepeating, inputRef]);

  useEffect(() => stopRepeating, [stopRepeating]);

  /*
   * The ruler outlives the gesture by one fade. Keeping it mounted through the
   * exit is what lets the value fade back in rather than snap; the ruler itself
   * says when that fade is done, so the duration stays a token rather than
   * being a number repeated here.
   */
  const dropRuler = useCallback(() => {
    setScrub((previous) => (previous?.phase === "out" ? null : previous));
  }, []);

  useEffect(() => {
    if (engaged || scrub === null || scrub.phase === "out") return undefined;
    setScrub({ ...scrub, phase: "out" });
    // A transition that never runs never ends, and a theme is free to zero the
    // duration, so the fade's own signal gets a backstop rather than a rival.
    const backstop = setTimeout(dropRuler, 1000);
    return () => clearTimeout(backstop);
  }, [engaged, scrub, dropRuler]);

  useEffect(() => {
    if (!engaged) setReadout(null);
  }, [engaged]);

  return {
    scrub,
    engaged,
    beginScrub,
    beginPress,
    dropRuler,
    readout: engaged ? readout : null,
  };
}

/**
 * Wheel stepping, owned here rather than taken from `allowWheelScrub`.
 *
 * Base UI's version steps by `largeStep` on shift, which this field does not
 * have. The rest is the same shape: only while focused, only on the vertical
 * axis, and never under a modifier — ctrl is the browser's zoom, and the others
 * are reserved for nothing, which is the point.
 */
function useWheelStepping({
  inputRef,
  adjustable,
  canStep,
  bumpBy,
  commit,
  valueRef,
}: {
  inputRef: { current: HTMLInputElement | null };
  adjustable: boolean;
  canStep: (towards: 1 | -1) => boolean;
  bumpBy: (steps: number, reason: NumberFieldRoot.ChangeEventReason) => void;
  commit: (value: number | null, reason: NumberFieldRoot.CommitEventReason) => void;
  valueRef: { current: number | null };
}) {
  const burst = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => {
    const input = inputRef.current;
    if (!adjustable || !input) return undefined;

    const handleWheel = (event: WheelEvent) => {
      if (event.ctrlKey || event.shiftKey || event.altKey || event.metaKey) return;
      if (input.ownerDocument.activeElement !== input) return;
      const { deltaX, deltaY } = event;
      if (deltaY === 0 || Math.abs(deltaY) < Math.abs(deltaX)) return;

      const towards = (deltaY < 0 ? 1 : -1) as 1 | -1;
      if (!canStep(towards)) return;

      // Non-passive, so the page does not scroll out from under the field.
      event.preventDefault();
      bumpBy(towards, "wheel");

      // One flick of a wheel is many events; the interaction is the burst.
      clearTimeout(burst.current);
      burst.current = setTimeout(() => commit(valueRef.current, "wheel"), WHEEL_COMMIT_DELAY);
    };

    input.addEventListener("wheel", handleWheel, { passive: false });
    return () => input.removeEventListener("wheel", handleWheel);
  }, [inputRef, adjustable, canStep, bumpBy, commit, valueRef]);

  useEffect(() => () => clearTimeout(burst.current), []);
}

/**
 * Escape abandons the edit and restores the value the field had when it took
 * focus, which is the other half of `onValueCommitted`: every interaction ends
 * either committed or cancelled, and the user can always get back.
 *
 * Skipped while scrubbing, where the gesture has a nearer origin of its own.
 */
function useEscapeRevert({
  inputRef,
  value,
  valueRef,
  setValue,
  onCancel,
  scrubbing,
}: {
  inputRef: { current: HTMLInputElement | null };
  value: number | null;
  valueRef: { current: number | null };
  setValue: (value: number | null, reason: NumberFieldRoot.ChangeEventReason) => void;
  onCancel: ((value: number | null) => void) | undefined;
  scrubbing: boolean;
}) {
  const origin = useRef<number | null>(value);

  useEffect(() => {
    const input = inputRef.current;
    if (!input) return undefined;

    const handleFocus = () => {
      origin.current = valueRef.current;
    };
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || scrubbing || event.defaultPrevented) return;
      const restored = origin.current;
      if (restored === valueRef.current) {
        input.blur();
        return;
      }
      event.preventDefault();
      setValue(restored, "none");
      onCancel?.(restored);
      input.blur();
    };

    input.addEventListener("focus", handleFocus);
    input.addEventListener("keydown", handleKeyDown);
    return () => {
      input.removeEventListener("focus", handleFocus);
      input.removeEventListener("keydown", handleKeyDown);
    };
  }, [inputRef, valueRef, setValue, onCancel, scrubbing]);
}

/* -------------------------------------------------------------------------
 * Parts
 * ---------------------------------------------------------------------- */

/**
 * A region of the field that scrubs when dragged.
 *
 * `ScrubArea` is kept for what only it can do — pointer lock, and a virtual
 * cursor that wraps at the viewport edge instead of stopping at it, so a long
 * drag is never cut short by the screen. Its increment rule is switched off;
 * `useAdjustment` reads the same pointer stream and applies ClaraLight's.
 */
function ScrubHandle({
  enabled,
  engaged,
  onScrubStart,
  className,
  children,
}: {
  enabled: boolean;
  /** Whether the drag has won the interaction; a press alone shows nothing. */
  engaged: boolean;
  onScrubStart: (event: ReactPointerEvent) => void;
  className?: string;
  children?: ReactNode;
}) {
  return (
    <NumberField.ScrubArea
      pixelSensitivity={SCRUB_SENSITIVITY_OFF}
      onPointerDown={onScrubStart}
      className={cn(className, enabled && "cursor-ew-resize")}
    >
      {children}
      {/*
       * Base UI shows this the moment a pointer goes down, since that is when
       * it takes the pointer lock. Here the lock is taken before the
       * interaction has been decided, so the cursor waits for the drag — a
       * click on a chevron must not blink a scrub cursor on its way past.
       */}
      <NumberField.ScrubAreaCursor className={cn(!engaged && "invisible")}>
        <ResizeCursor />
      </NumberField.ScrubAreaCursor>
    </NumberField.ScrubArea>
  );
}

/** The horizontal-resize pointer, drawn because pointer lock hides the real one. */
function ResizeCursor() {
  return (
    <svg width="26" height="14" viewBox="0 0 26 14" fill="none" aria-hidden="true">
      <title>Scrub</title>
      <path
        d="M19.5 3.5 24 7l-4.5 3.5M6.5 3.5 2 7l4.5 3.5M3 7h20"
        stroke="var(--cl-background)"
        strokeWidth="3.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path
        d="M19.5 3.5 24 7l-4.5 3.5M6.5 3.5 2 7l4.5 3.5M3 7h20"
        stroke="var(--cl-foreground)"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * The two chevrons at the trailing edge, and the strip they sit in.
 *
 * The whole strip is a scrub handle, the chevrons included. That is the point:
 * a field with no prefix has nothing else to grab, and the few pixels of strip
 * around two 18x10 buttons are not a drag target anyone could hit. The press
 * and the drag are arbitrated by distance in `useAdjustment` rather than by
 * region, so a chevron can be clicked, held, or dragged from.
 */
function Stepper({
  axis,
  leading,
  enabled,
  engaged,
  controls,
  canStep,
  onScrubStart,
  onPress,
}: {
  axis: "vertical" | "horizontal";
  leading: 1 | -1;
  enabled: boolean;
  engaged: boolean;
  /** The input the buttons drive, for `aria-controls`. */
  controls: string;
  canStep: (towards: 1 | -1) => boolean;
  onScrubStart: (event: ReactPointerEvent) => void;
  onPress: (towards: 1 | -1, event: ReactPointerEvent) => void;
}) {
  return (
    <ScrubHandle
      enabled={enabled}
      engaged={engaged}
      onScrubStart={onScrubStart}
      className="flex shrink-0 items-center self-stretch"
    >
      <span
        className={cn(
          "flex w-(--cl-number-stepper-width)",
          axis === "vertical" ? "flex-col" : "flex-row",
        )}
      >
        <ChevronButton
          axis={axis}
          towards={leading}
          pointing={axis === "vertical" ? "up" : "left"}
          enabled={enabled && canStep(leading)}
          controls={controls}
          onPress={onPress}
        />
        <ChevronButton
          axis={axis}
          towards={-leading as 1 | -1}
          pointing={axis === "vertical" ? "down" : "right"}
          enabled={enabled && canStep(-leading as 1 | -1)}
          controls={controls}
          onPress={onPress}
        />
      </span>
    </ScrubHandle>
  );
}

/** One slot per chevron, so the strip is addressable from a test or a theme. */
const STEP_SLOT = {
  up: "number-input-step-up",
  down: "number-input-step-down",
  left: "number-input-step-left",
  right: "number-input-step-right",
} as const;

/**
 * One chevron.
 *
 * A plain button rather than `NumberField.Increment`, for one reason: Base UI's
 * stepper calls `preventDefault()` on pointer-down, and `ScrubArea` stands down
 * on anything already default-prevented — so a chevron built from it can never
 * be dragged from. Leaving the event alone is what lets the same press become
 * either a step or a scrub.
 *
 * It follows that the stepping is ours too, and it happens on release: see
 * `useAdjustment`, which also owns the hold.
 *
 * At a bound the button is `aria-disabled` rather than `disabled`. A disabled
 * button dispatches no pointer events at all, which would put a dead patch in
 * the middle of the scrub handle exactly when the user wants to drag the other
 * way — the state has to be announced without taking the surface away.
 */
function ChevronButton({
  axis,
  towards,
  pointing,
  enabled,
  controls,
  onPress,
}: {
  axis: "vertical" | "horizontal";
  towards: 1 | -1;
  pointing: NumberInputDirection;
  enabled: boolean;
  controls: string;
  onPress: (towards: 1 | -1, event: ReactPointerEvent) => void;
}) {
  return (
    <button
      type="button"
      data-cl-slot={STEP_SLOT[pointing]}
      // Keyboard users step from the input itself, which carries the spinbutton
      // semantics; the buttons are a pointer affordance and stay out of the
      // tab order, as Base UI's own steppers do.
      tabIndex={-1}
      aria-label={towards > 0 ? "Increase" : "Decrease"}
      aria-controls={controls}
      aria-disabled={!enabled || undefined}
      data-disabled={!enabled || undefined}
      onPointerDown={(event) => onPress(towards, event)}
      className={cn(
        "flex items-center justify-center text-foreground-secondary select-none",
        "transition-colors duration-(--cl-duration-fast) ease-cl-out",
        "hover:text-foreground data-[disabled]:text-foreground-disabled",
        // One button is `step-width` across the strip and `step-height` along
        // it; a horizontal stepper is the same pair turned a quarter turn.
        axis === "vertical"
          ? "h-(--cl-number-step-height) w-(--cl-number-step-width)"
          : "h-(--cl-number-step-width) w-(--cl-number-step-height)",
      )}
    >
      <Chevron pointing={pointing} />
    </button>
  );
}

/**
 * The glyph, per direction: its drawing box and the stroke inside it.
 *
 * These are not theme tokens and should not be. They are the coordinates of a
 * drawing — the box exists to give the path a frame — and the path itself is
 * meaningless outside it, so splitting the two would leave a token nobody could
 * change safely. The size the glyph is *placed* at is the theme's, above.
 */
const CHEVRON = {
  up: { boxWidth: 8, boxHeight: 4.5, box: "0 0 8 4.5", d: "M0.7 3.8 L4 0.7 L7.3 3.8" },
  down: { boxWidth: 8, boxHeight: 4.5, box: "0 0 8 4.5", d: "M0.7 0.7 L4 3.8 L7.3 0.7" },
  left: { boxWidth: 4.5, boxHeight: 8, box: "0 0 4.5 8", d: "M3.8 0.7 L0.7 4 L3.8 7.3" },
  right: { boxWidth: 4.5, boxHeight: 8, box: "0 0 4.5 8", d: "M0.7 0.7 L3.8 4 L0.7 7.3" },
} as const;

function Chevron({ pointing }: { pointing: NumberInputDirection }) {
  const { boxWidth, boxHeight, box, d } = CHEVRON[pointing];

  return (
    <svg width={boxWidth} height={boxHeight} viewBox={box} aria-hidden="true">
      <path
        d={d}
        fill="none"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * The ruler drawn under the pointer while scrubbing.
 *
 * Canvas rather than SVG: at the finest pitch a field holds dozens of ticks,
 * each with its own opacity, and repainting that as elements would be a
 * reconciliation pass per frame for marks nobody can click.
 *
 * Ticks stop where the value does. Past `min` or `max` there is no step left to
 * take, so drawing a tick there would promise one — the range is visible in the
 * gesture instead of being discovered by pushing into a wall.
 */
function ScrubRuler({
  progress,
  spacing,
  increase,
  decrease,
  revealed,
  onFadedOut,
}: {
  progress: number;
  spacing: number;
  increase: number | null;
  decrease: number | null;
  revealed: boolean;
  /** Called once the exit fade has played, so the ruler can be dropped. */
  onFadedOut: () => void;
}) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const context = canvas?.getContext("2d");
    if (!canvas || !context) return;

    const ratio = canvas.ownerDocument.defaultView?.devicePixelRatio ?? 1;
    const { width, height } = canvas.getBoundingClientRect();
    if (width === 0 || height === 0) return;

    const pixelWidth = Math.round(width * ratio);
    const pixelHeight = Math.round(height * ratio);
    if (canvas.width !== pixelWidth) canvas.width = pixelWidth;
    if (canvas.height !== pixelHeight) canvas.height = pixelHeight;

    context.setTransform(ratio, 0, 0, ratio, 0, 0);
    context.clearRect(0, 0, width, height);
    context.strokeStyle = getComputedStyle(canvas).color;
    context.lineCap = "round";

    const center = width / 2;
    const half = Math.max(1, center);
    const lineHeight = height * 0.55;
    const top = (height - lineHeight) / 2;
    const bottom = top + lineHeight;
    const phase = progress * spacing;
    const count = Math.ceil(width / spacing) + 2;

    context.lineWidth = 1;
    for (let index = -count; index <= count; index += 1) {
      if (increase !== null && index < -increase) continue;
      if (decrease !== null && index > decrease) continue;
      const x = center + phase + index * spacing;
      if (x < -spacing || x > width + spacing) continue;
      // Ticks fade out towards the edges so the eye stays on the centre line,
      // which is the only one that means anything.
      const distance = Math.min(1, Math.abs(x - center) / half);
      const opacity = (1 - distance) ** 1.65 * 0.72;
      if (opacity <= 0.01) continue;
      context.globalAlpha = opacity;
      context.beginPath();
      context.moveTo(x, top);
      context.lineTo(x, bottom);
      context.stroke();
    }

    context.lineWidth = 1.25;
    context.globalAlpha = 0.96;
    context.beginPath();
    context.moveTo(center, top);
    context.lineTo(center, bottom);
    context.stroke();
  }, [progress, spacing, increase, decrease]);

  return (
    /*
     * The canvas is wrapped rather than hidden directly: an empty `<canvas>` is
     * an interactive element as far as ARIA is concerned, so the decoration is
     * declared on a box around it. The ruler restates the value the input
     * already announces, and the input is what should be read during a scrub.
     */
    <span
      aria-hidden="true"
      onTransitionEnd={revealed ? undefined : onFadedOut}
      data-cl-slot="number-input-ruler"
      className={cn(
        "pointer-events-none absolute inset-0 text-foreground",
        "transition-opacity ease-cl-out motion-reduce:duration-(--cl-duration-reduced)",
        revealed
          ? "opacity-100 duration-(--cl-duration-fast)"
          : "opacity-0 duration-(--cl-duration-exit)",
      )}
    >
      <canvas ref={canvasRef} className="h-full w-full" />
    </span>
  );
}

/**
 * The value, shown above the field while it is being scrubbed.
 *
 * A tooltip and not a popover: this is a readout nobody can interact with, and
 * a popover would take focus away from the field the gesture is driving. The
 * surface is `AnchoredSurface`, so the tail is part of the shape and the whole
 * thing grows out of the point it is aiming at — the same construction as
 * `Popover` and `Tooltip`.
 *
 * Digits roll rather than swap, through Scritto, which is the web's equivalent
 * of the numeric-text content transition the Flutter overlay uses. Only the
 * digits that changed move; the unit beside them holds still.
 */
function ScrubReadout({
  anchor,
  open,
  value,
  suffix,
}: {
  anchor: { current: HTMLElement | null };
  open: boolean;
  value: string;
  suffix: ReactNode;
}) {
  const positionerRef = useRef<HTMLDivElement>(null);
  const margin = useThemedNumber(positionerRef, "--cl-anchor-margin");

  return (
    <Tooltip.Root open={open} trackCursorAxis="none">
      <Tooltip.Portal keepMounted={false}>
        <Tooltip.Positioner
          ref={positionerRef}
          anchor={anchor}
          side="top"
          align="center"
          sideOffset={() => themedNumber(positionerRef.current, "--cl-anchor-gap") ?? 0}
          collisionPadding={margin}
          sticky
          className="pointer-events-none z-50 outline-none"
        >
          <AnchoredSurface asChild radius="panel" side="top" wrapperClassName="w-fit">
            <Tooltip.Popup
              aria-hidden="true"
              data-cl-slot="number-input-readout"
              className={cn(
                "cl-exit-sentinel cl-frost border-outline-strong shadow-none",
                "flex min-w-20 items-baseline justify-center whitespace-nowrap",
                "[--cl-anchored-padding-x:var(--cl-number-readout-padding-x)]",
                "[--cl-anchored-padding-y:var(--cl-number-readout-padding-y)]",
              )}
            >
              {/*
               * `display` and `headline` are the 30px and 18px steps the Flutter
               * overlay uses; both are borrowed into the mono family here, so
               * each takes back the weight and tracking of a numeric readout.
               */}
              <Scritto
                value={value}
                className="font-mono font-semibold text-display text-foreground tabular-nums tracking-normal"
              />
              {suffix === undefined ? null : (
                <span className="font-mono font-normal text-foreground-tertiary text-headline tracking-normal">
                  {suffix}
                </span>
              )}
              <Tooltip.Arrow data-cl-anchor-probe="" className="cl-anchor-probe" />
            </Tooltip.Popup>
          </AnchoredSurface>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}
